let timer;async function tick(){if(ha.connected)await poll();if(gridSettings.autoRefresh&&influxHistory.at&&influxSettings.password&&!job?.running&&config.location.latitude!==null&&Date.now()-(gridState.attemptedAt||0)>86400000)void gridBackfill(gridState.backfilledAt?3:gridSettings.initialDays);if(influxSettings.autoRefresh&&influxHistory.completedAt&&Date.now()-influxHistory.completedAt>DAY&&!job?.running&&config.location.latitude!==null)void influxImport(false,true);timer=setTimeout(tick,config.pollSeconds*1000);timer.unref();}void tick();
